export const bundledExamples = {"/examples/01_multi_output.js":"// No DAW or manual MIDI connection needed. Choose this Run file and press Run.\n// Stop releases all three loops. The native sound rack stays enabled for Keyboard.\nawait enableSoundChip(\"ym2612\");\nawait enableSoundChip(\"sega-psg\");\nsetBpm(120);\n\nconst piano = midi.output(\"tetorica-ym2612\", { channel: 1 });\nconst bass = midi.output(\"tetorica-ym2612\", { channel: 2 });\nconst lead = midi.output(\"tetorica-sega-psg\", { channel: 1 });\n\nliveLoop(\"piano\", async () => {\n  piano.play(cycle([\"C4\", \"E4\", \"G4\", \"E4\"]), { duration: 0.4, velocity: 80 });\n  await beat(0.5);\n});\nliveLoop(\"bass\", async () => {\n  bass.play(cycle([\"C3\", \"G2\"]), { duration: 0.8, velocity: 90 });\n  await beat(1);\n});\nliveLoop(\"lead\", async () => {\n  lead.play(cycle([\"C5\", \"E5\", \"G5\", \"E5\"]), { duration: 0.15, velocity: 65 });\n  await beat(0.25);\n});\n// PSG CH10 is fixed white noise. YM2612 currently uses a fixed FM patch on every CH.\n// External ports can instead be selected by their unique name in midi.output().\n","/examples/02_assigned_outputs.js":"// Press Run: internal destinations work without manual MIDI assignments.\n// To use assignments instead, set MIDI_OUTPUT_01 / 02 in MIDI connections,\n// then replace \"tetorica-ym2612\" with MIDI_OUTPUT_01 (without quotes)\n// and \"tetorica-sega-psg\" with MIDI_OUTPUT_02 in the output calls below.\nawait enableSoundChip(\"ym2612\");\nawait enableSoundChip(\"sega-psg\");\nconst piano = midi.output(\"tetorica-ym2612\", { channel: 1 });\nconst bass = midi.output(\"tetorica-ym2612\", { channel: 2 });\nconst lead = midi.output(\"tetorica-sega-psg\", { channel: 1 });\nliveLoop(\"piano\", async () => {\n  piano.play(\"C4\", { duration: 0.4 });\n  await beat(0.5);\n});\nliveLoop(\"bass\", async () => {\n  bass.play(\"C3\", { duration: 0.8 });\n  await beat(1);\n});\nliveLoop(\"lead\", async () => {\n  lead.play(\"G4\", { duration: 0.2 });\n  await beat(0.25);\n});\n"};
